def is_anagram(a, b):
    """True if a and b use the same letters."""
    # Normalize: remove spaces, convert to lowercase
    a_normalized = a.replace(' ', '').lower()
    b_normalized = b.replace(' ', '').lower()

    # Count character frequencies
    a_counts = {}
    for char in a_normalized:
        a_counts[char] = a_counts.get(char, 0) + 1

    b_counts = {}
    for char in b_normalized:
        b_counts[char] = b_counts.get(char, 0) + 1

    return a_counts == b_counts
```

