        """When the user is deleted (KeyError), return 'Guest'."""
        mock_store.get_user.side_effect = KeyError("User not found")
        result = profile.display_name("deleted_user")
        self.assertEqual(result, "Guest")

    @mock.patch('profile.store')
    def test_nonexistent_user_returns_guest(self, mock_store):
        """When the user ID does not exist, return 'Guest'."""
        mock_store.get_user.side_effect = KeyError("No such user")
        result = profile.display_name("unknown_id")
        self.assertEqual(result, "Guest")

    @mock.patch('profile.store')
    def test_empty_user_id_returns_guest(self, mock_store):
        """When an empty string is passed, return 'Guest' if it raises KeyError."""
        mock_store.get_user.side_effect = KeyError("Empty ID")
        result = profile.display_name("")
        self.assertEqual(result, "Guest")

