    def test_special_characters_in_user_id_returns_guest(self, mock_store):
        """When user_id contains special characters, return 'Guest' if KeyError."""
        mock_store.get_user.side_effect = KeyError("Special chars")
        result = profile.display_name("<deleted>")
        self.assertEqual(result, "Guest")

    @mock.patch('profile.store')
    def test_user_with_none_name_returns_guest(self, mock_store):
        """If the user exists but name is None, handle gracefully or return name."""
