        mock_read.return_value = 29.9
        self.assertFalse(alerts.too_hot('sensor1'))

    @patch('alerts.read')
    def test_hot_above_threshold(self, mock_read):
        """Above 30°C, should be too hot."""
        mock_read.return_value = 30.1
        self.assertTrue(alerts.too_hot('sensor1'))

