    def test_hot_at_high_temperature(self, mock_read):
        """At 100°C, should be too hot."""
        mock_read.return_value = 100.0
        self.assertTrue(alerts.too_hot('sensor1'))

    @patch('alerts.read')
    def test_not_hot_at_zero(self, mock_read):
        """At 0°C, should not be too hot."""
        mock_read.return_value = 0.0
        self.assertFalse(alerts.too_hot('sensor1'))

