def parse_version(text):
    """'1.2.3' -> (1, 2, 3)"""
    if text is None or not isinstance(text, str):
        return None

    text = text.strip()
    if not text:
        return None

    if text.startswith('v'):
        text = text[1:]

    parts = text.split('.')

    # Check for malformed input: must have exactly 3 parts, all numeric
    if len(parts) != 3:
        return None

    result = []
    for p in parts:
        # Each part must be a valid integer string (no leading zeros except for '0' itself is fine, but we just check if it's a valid integer)
        if not p:
            return None
        try:
            val = int(p)
        except ValueError:
            return None
        result.append(val)

    return tuple(result)
