        uploads.user_file('/uploads', '../x')
        assert False, "Expected ValueError"
    except ValueError:
        pass


def test_deep_parent_escape_refused():
    """A name with multiple '..' that escapes base should raise ValueError."""
    try:
        uploads.user_file('/uploads', 'sub/../../x')
        assert False, "Expected ValueError"
    except ValueError:
        pass


def test_absolute_path_refused():
    """An absolute path should raise ValueError."""
    try:
