    def test_unique_words_empty(self):
        self.assertEqual(unique_words(""), [])

    def test_unique_words_single(self):
        self.assertEqual(unique_words("hello"), ["hello"])

    def test_unique_words_case_sensitive(self):
        self.assertEqual(unique_words("Hello hello"), ["Hello", "hello"])

    def test_unique_words_sorted(self):
        self.assertEqual(unique_words("zebra alpha alpha"), ["alpha", "zebra"])


if __name__ == '__main__':
