from lib.names import initials


def test_signature_basic():
    """Check the required behaviour: 'A.L. (Engineer)'."""
    assert signature('Ada Lovelace', 'Engineer') == 'A.L. (Engineer)'


def test_signature_single_name():
    """Single name should produce one initial."""
    assert signature('Ada', 'Engineer') == 'A. (Engineer)'


def test_signature_three_names():
    """Three names should produce three initials."""
    assert signature('Ada Lovelace Foo', 'Engineer') == 'A.L.F. (Engineer)'


def test_signature_empty_role():
    """Empty role should still work."""
    assert signature('Ada Lovelace', '') == 'A.L. ()'


def test_signature_special_chars_in_name():
    """Names with special characters should be handled gracefully."""
    assert signature('Ada-Lovelace', 'Engineer') == 'A.-L. (Engineer)'


def test_signature_spaces_in_name():
    """Extra spaces between names should not break initials."""
    assert signature('Ada   Lovelace', 'Engineer') == 'A.L. (Engineer)'


def test_signature_unicode_name():
    """Unicode names should produce correct initials."""
    assert signature('Äda Lovelace', 'Engineer') == 'Ä.L. (Engineer)'


def test_signature_role_with_parentheses():
    """Role containing parentheses should be preserved."""
    assert signature('Ada Lovelace', '(Engineer)') == 'A.L. ((Engineer))'

